<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import CodexWaterBall from './CodexWaterBall.vue'
import { buildCodexCompactPresentation } from '../domain/codexPresentation'
import { resolveCompanionWaterBallPresentation } from '../domain/companionPresentation'
import { codexThemeCssVars, resolveCodexExpandedCardTheme } from '../domain/codexAppearance'
import type { CodexColorSettings, CodexCounterColors, CodexExpandedCardAppearanceSettings, CodexSettings } from '../domain/codex'
import type { CodexRuntimeView } from '../runtime/codexController'

const props = defineProps<{ snapshot: CodexRuntimeView; mode: 'water' | 'card' }>()
const emit = defineEmits<{ dispatch: [actionId: string, args?: Record<string, unknown>]; 'update:mode': [mode: 'water' | 'card'] }>()
const selected = ref('base')
const hovered = ref<string | null>(null)
const expanded = ref<Set<string>>(new Set())
const exploded = computed(() => expanded.value.size > 0)
const yaw = ref(0), pitch = ref(0)
let pointerStart: { x: number; y: number; yaw: number; pitch: number } | null = null
const cardLayerIds = ['surface','accent','secondary','codexQuota','foreground']
function selectableLayer(id: string) { return props.mode === 'water' ? layers.some(layer => layer.id === id) || (['input','active','unread'].includes(id) && Boolean(compact.value.taskCounts[id as 'input' | 'active' | 'unread'])) : cardLayerIds.includes(id) }
function toggleAll() { expanded.value = expanded.value.size ? new Set() : new Set(props.mode === 'water' ? [...layers.map(layer => layer.id), ...(['input','active','unread'] as const).filter(id => compact.value.taskCounts[id] > 0)] : cardLayerIds) }
function detach() { if (selectableLayer(selected.value)) expanded.value = new Set([...expanded.value, selected.value]) }
function restore() { const next = new Set(expanded.value); next.delete(selected.value); expanded.value = next }
function dragStart(event: PointerEvent) { if (event.button === 0) pointerStart = { x: event.clientX, y: event.clientY, yaw: yaw.value, pitch: pitch.value } }
function partFromTarget(target: Element) { return target.closest('.codex-water-ball__value') ? 'reading' : target.closest('.codex-water-ball__ring') ? 'ring' : target.closest('.codex-water-ball__liquid') ? 'liquid' : target.closest('.codex-water-ball') ? 'base' : null }
function dragMove(event: PointerEvent) { if (!pointerStart || !event.buttons) { hovered.value = partFromTarget(event.target as Element); return } yaw.value = pointerStart.yaw + (event.clientX-pointerStart.x)*.006; pitch.value = Math.max(-.7, Math.min(.7, pointerStart.pitch - (event.clientY-pointerStart.y)*.006)) }
function stageKey(event: KeyboardEvent) { if (event.key === 'Home') { yaw.value = 0; pitch.value = 0; event.preventDefault(); return } if (!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)) return; event.preventDefault(); yaw.value += event.key === 'ArrowRight' ? .1 : event.key === 'ArrowLeft' ? -.1 : 0; pitch.value = Math.max(-.7, Math.min(.7, pitch.value + (event.key === 'ArrowUp' ? .1 : event.key === 'ArrowDown' ? -.1 : 0))) }
function pickBall(event: MouseEvent) { selected.value = partFromTarget(event.target as Element) || 'base' }
function sampleLayer(id: string) { const p = realBallProps.value; if (!expanded.value.has(id)) return false; if (id === 'liquid') return !(p.liquidPercent ?? p.primary?.bucket.remainingPercent); if (id === 'ring') return !(p.ringPercent ?? (p.primary?.kind === 'weekly' ? p.primary.bucket.remainingPercent : p.secondary?.bucket.remainingPercent)); return false }
function layerProps(id: string) { const p = realBallProps.value; return sampleLayer(id) ? { ...p, ...(id === 'liquid' ? { liquidPercent: 62 } : { ringPercent: 62 }) } : p }
function counterTransform(id: string) { const offsets: Record<string,string> = { input: 'translate3d(-35px,20px,65px)', active: 'translate3d(35px,-5px,65px)', unread: 'translate3d(35px,20px,65px)' }; return expanded.value.has(id) ? offsets[id] : 'translate3d(0,0,0)' }
const hue = ref(0)
const saturation = ref(0)
const brightness = ref(1)
const liquidColorChannel = ref<'A' | 'B'>('A')
const waterParts = [
  ['base', '球体底色'], ['liquid', '液体'], ['ring', '额度环'], ['track', '环形轨道'], ['reading', '读数文字'],
  ['input', '待输入角标'], ['active', '进行中角标'], ['unread', '未读角标'], ['healthy', '充足'], ['warning', '提醒'], ['critical', '紧张']
] as const
const cardParts = [
  ['surface', '面板底色'], ['surfaceRaised', '内层块'], ['border', '边框'], ['foreground', '主文字'], ['secondary', '次文字'],
  ['accent', '选中强调'], ['focus', '焦点'], ['running', '进行中'], ['pending', '完成未读'], ['codexQuota', 'Codex 额度'], ['claudeQuota', 'Claude 额度'], ['cursorQuota', 'Cursor 额度（只读）']
] as const
const availableParts = computed(() => props.mode === 'water' ? waterParts : cardParts.filter(([key]) => (key !== 'claudeQuota' || props.snapshot.settings.providers.claude) && (key !== 'cursorQuota' || props.snapshot.settings.providers.cursor || props.snapshot.settings.magpieQuotaAccess)))
watch(() => props.mode, mode => { selected.value = mode === 'water' ? 'base' : 'surface'; expanded.value = new Set() })
const compact = computed(() => buildCodexCompactPresentation({ quota: props.snapshot.quota, compactFields: props.snapshot.settings.compactFields, conversationInboxEnabled: props.snapshot.settings.conversationInboxEnabled, taskCounts: props.snapshot.taskState.dynamic.compactCounts }))
const companion = computed(() => resolveCompanionWaterBallPresentation({ providers: props.snapshot.settings.providers, claudeQuota: props.snapshot.claudeQuota, claudeEnvironment: props.snapshot.claudeEnvironment, magpieQuota: props.snapshot.companion?.magpieQuota }, { primary: compact.value.primary, secondary: compact.value.secondary }))
const cardStyle = computed(() => codexThemeCssVars(resolveCodexExpandedCardTheme(props.snapshot.settings.colors, props.snapshot.settings.expandedCardAppearance, compact.value.primary?.bucket.remainingPercent ?? 100)))
const realBallProps = computed(() => ({ primary: compact.value.primary, secondary: compact.value.secondary, stateLabel: compact.value.stateLabel, label: compact.value.ariaLabel, appearance: props.snapshot.settings.waterAppearance, colors: props.snapshot.settings.colors, percentOverride: companion.value.percentOverride, scopedPercent: companion.value.scopedPercent, percentProviderLabel: companion.value.percentProviderLabel, liquidPercent: companion.value.liquidPercent, ringPercent: companion.value.ringPercent, quotaGrid: companion.value.quotaGrid.enabled ? companion.value.quotaGrid.cells : null, decorative: true }))
const layers = [ { id: 'base', name: '球体与高光', x: -56, y: -18, z: -40 }, { id: 'liquid', name: '水波', x: 58, y: 10, z: 35 }, { id: 'track', name: '外环轨道', x: -32, y: -62, z: 8 }, { id: 'ring', name: '额度环', x: 48, y: -60, z: 65 }, { id: 'reading', name: '读数', x: 0, y: 57, z: 90 } ] as const
function update(patch: Partial<CodexSettings>) { emit('dispatch', 'codex.settings.update', { settings: patch }) }
function updateInner(key: string, value: string | number | boolean) { const water = props.snapshot.settings.waterAppearance; update({ waterAppearance: { ...water, inner: { ...water.inner, [key]: value } } }) }
function updateOuter(key: string, value: string | number) { const water = props.snapshot.settings.waterAppearance; update({ waterAppearance: { ...water, outer: { ...water.outer, [key]: value } } }) }
const selectedColor = computed(() => {
  const s = props.snapshot.settings, k = selected.value
  if (props.mode === 'card') return k === 'cursorQuota' ? resolveCodexExpandedCardTheme(s.colors, s.expandedCardAppearance, compact.value.primary?.bucket.remainingPercent ?? 100).quotaCursor : s.expandedCardAppearance[k as keyof CodexExpandedCardAppearanceSettings] || '#000000'
  if (k === 'base') return s.colors.water
  if (k === 'liquid') return liquidColorChannel.value === 'A' ? s.waterAppearance.inner.fillColorA : s.waterAppearance.inner.fillColorB
  if (k === 'ring') return s.waterAppearance.outer.progressColor
  if (k === 'track') return s.waterAppearance.outer.trackColor
  if (k === 'reading') return s.waterAppearance.inner.percentColor
  if (k === 'input' || k === 'active' || k === 'unread') return s.counterColors[k as keyof CodexCounterColors]
  return s.colors[k as keyof CodexColorSettings] || '#000000'
})
function setColor(value: string) {
  const color = value.toUpperCase(), s = props.snapshot.settings, k = selected.value
  if (!/^#[0-9A-F]{6}$/.test(color) || (props.mode === 'card' && k === 'cursorQuota')) return
  if (props.mode === 'card') update({ expandedCardAppearance: { ...s.expandedCardAppearance, [k]: color } })
  else if (k === 'base') update({ colors: { ...s.colors, water: color } })
  else if (k === 'liquid') updateInner(liquidColorChannel.value === 'A' ? 'fillColorA' : 'fillColorB', color)
  else if (k === 'ring') update({ waterAppearance: { ...s.waterAppearance, outer: { ...s.waterAppearance.outer, colorMode: 'custom', progressColor: color } } })
  else if (k === 'track') updateOuter('trackColor', color)
  else if (k === 'reading') updateInner('percentColor', color)
  else if (k === 'input' || k === 'active' || k === 'unread') update({ counterColors: { ...s.counterColors, [k]: color } })
  else update({ colors: { ...s.colors, [k]: color } })
}
function loadColor(hex: string) { const nums = [1,3,5].map(i => parseInt(hex.slice(i,i+2),16) / 255); const max = Math.max(...nums), min = Math.min(...nums), d = max-min; let h = 0; if (d) { if (max===nums[0]) h=((nums[1]-nums[2])/d)%6; else if(max===nums[1]) h=(nums[2]-nums[0])/d+2; else h=(nums[0]-nums[1])/d+4; h=(h*60+360)%360 } hue.value=h; saturation.value=max?d/max:0; brightness.value=max }
watch(selectedColor, loadColor, { immediate: true })
function hsvHex() { const h=hue.value,s=saturation.value,v=brightness.value,c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c; const rgb=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return '#'+rgb.map(n=>Math.round((n+m)*255).toString(16).padStart(2,'0')).join('').toUpperCase() }
function pickSpectrum(event: PointerEvent) { if (props.mode === 'card' && selected.value === 'cursorQuota') return; const el=event.currentTarget as HTMLElement, r=el.getBoundingClientRect(); saturation.value=Math.max(0,Math.min(1,(event.clientX-r.left)/r.width));brightness.value=1-Math.max(0,Math.min(1,(event.clientY-r.top)/r.height));setColor(hsvHex()) }
function startPick(event: PointerEvent) { if (props.mode === 'card' && selected.value === 'cursorQuota') return; (event.currentTarget as HTMLElement).setPointerCapture(event.pointerId); pickSpectrum(event) }
function spectrumKey(event: KeyboardEvent) { if (props.mode === 'card' && selected.value === 'cursorQuota') return; if (!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)) return; event.preventDefault(); saturation.value=Math.max(0,Math.min(1,saturation.value+(event.key==='ArrowRight'?.02:event.key==='ArrowLeft'?-.02:0)));brightness.value=Math.max(0,Math.min(1,brightness.value+(event.key==='ArrowUp'?.02:event.key==='ArrowDown'?-.02:0)));setColor(hsvHex()) }
const selectedName = computed(() => availableParts.value.find(([id])=>id===selected.value)?.[1] || '部件')
</script>

<template>
  <div class="appearance-studio">
    <div class="appearance-studio-stage-wrap">
      <div class="appearance-studio-tabs"><button type="button" :class="{ active: mode === 'water' }" @click="emit('update:mode','water')">水球</button><button type="button" :class="{ active: mode === 'card' }" @click="emit('update:mode','card')">卡片</button><button type="button" class="appearance-assembly" @click="toggleAll">{{ exploded ? '聚合' : '散开' }}</button></div>
      <div class="appearance-studio-stage" tabindex="0" aria-label="模型预览，方向键旋转，Home 恢复视角，双击散开或聚合" @keydown="stageKey" @dblclick="toggleAll" @pointerdown="dragStart" @pointermove="dragMove" @pointerup="pointerStart = null" @pointerleave="pointerStart = null; hovered = null">
        <div v-if="mode === 'water'" class="appearance-studio-ball" :class="{ exploded }" :style="{ transform: `rotateX(${pitch}rad) rotateY(${yaw}rad)` }">
          <div v-if="!exploded" :class="['appearance-complete', `selected-${selected}`, hovered ? `hovered-${hovered}` : '']" @click="pickBall"><CodexWaterBall v-bind="realBallProps" /></div>
          <div v-for="layer in exploded ? layers : []" :key="layer.id" class="appearance-layer" :class="[`layer-${layer.id}`, { selected: selected === layer.id }]" :style="{ transform: expanded.has(layer.id) ? `translate3d(${layer.x}px,${layer.y}px,${layer.z}px)` : 'translate3d(0,0,0)' }" @click.stop="selected = layer.id"><CodexWaterBall v-bind="layerProps(layer.id)" /><button type="button" class="appearance-layer-label" @click.stop="selected = layer.id">{{ layer.name }}{{ sampleLayer(layer.id) ? ' · 示例' : '' }}</button></div>
          <button v-if="compact.taskCounts.input" type="button" :style="{ background: snapshot.settings.counterColors.input, transform: counterTransform('input') }" class="appearance-counter input" @click.stop="selected = 'input'">{{ compact.taskCounts.input }}</button>
          <button v-if="compact.taskCounts.active" type="button" :style="{ background: snapshot.settings.counterColors.active, transform: counterTransform('active') }" class="appearance-counter active" @click.stop="selected = 'active'">{{ compact.taskCounts.active }}</button>
          <button v-if="compact.taskCounts.unread" type="button" :style="{ background: snapshot.settings.counterColors.unread, transform: counterTransform('unread') }" class="appearance-counter unread" @click.stop="selected = 'unread'">{{ compact.taskCounts.unread }}</button>
        </div>
        <div v-else class="appearance-card" :class="{ exploded }" :style="[cardStyle, { transform: `rotateX(${pitch}rad) rotateY(${yaw}rad)` }]">
          <button type="button" class="appearance-card-surface" :class="{ selected: selected === 'surface' }" :style="{ transform: expanded.has('surface') ? 'translate3d(0px,0px,-35px)' : 'translate3d(0,0,0)' }" @click="selected = 'surface'" />
          <button type="button" class="appearance-card-tabs" :class="{ selected: selected === 'accent' }" :style="{ transform: expanded.has('accent') ? 'translate3d(0px,-34px,50px)' : 'translate3d(0,0,0)' }" @click="selected = 'accent'">动态　　已完成　　已隐藏　　项目</button>
          <button type="button" class="appearance-card-search" :class="{ selected: selected === 'secondary' }" :style="{ transform: expanded.has('secondary') ? 'translate3d(-25px,-12px,70px)' : 'translate3d(0,0,0)' }" @click="selected = 'secondary'">⌕　别名|任务|项目</button>
          <button type="button" class="appearance-card-quota" :class="{ selected: selected === 'codexQuota' }" :style="{ transform: expanded.has('codexQuota') ? 'translate3d(24px,8px,90px)' : 'translate3d(0,0,0)' }" @click="selected = 'codexQuota'">{{ compact.primary?.longLabel || '额度' }}　{{ compact.primary ? `${compact.primary.bucket.remainingPercent}%` : '—' }}</button>
          <button type="button" class="appearance-card-task" :class="{ selected: selected === 'foreground' }" :style="{ transform: expanded.has('foreground') ? 'translate3d(0px,30px,110px)' : 'translate3d(0,0,0)' }" @click="selected = 'foreground'">●　{{ compact.taskCounts.active }} 个进行中任务</button>
        </div>
      </div>
    </div>
    <div class="appearance-studio-editor">
      <label><span>配置部件</span><select v-model="selected" class="codex-select" aria-label="选择配置部件"><option v-for="[id,name] in availableParts" :key="id" :value="id">{{ name }}</option></select></label>
      <div class="appearance-color-heading"><strong>{{ selectedName }}</strong><span>{{ selectedColor }}</span></div><p v-if="mode === 'card' && selected === 'cursorQuota'" class="appearance-readonly">Cursor 颜色由主题自动派生，只读。</p>
      <div class="appearance-spectrum" role="slider" :tabindex="mode === 'card' && selected === 'cursorQuota' ? -1 : 0" :aria-disabled="mode === 'card' && selected === 'cursorQuota'" aria-valuemin="0" aria-valuemax="100" :aria-valuenow="Math.round(saturation * 100)" aria-label="颜色饱和度与亮度" :aria-valuetext="selectedColor" :style="{ backgroundColor: `hsl(${hue},100%,50%)` }" @pointerdown="startPick" @pointermove="event => { if (event.buttons) pickSpectrum(event) }" @keydown="spectrumKey"><i :style="{ left: `${saturation * 100}%`, top: `${(1 - brightness) * 100}%` }" /></div>
      <input class="appearance-hue" type="range" min="0" max="359" :disabled="mode === 'card' && selected === 'cursorQuota'" :value="hue" aria-label="色相" @input="hue = Number(($event.target as HTMLInputElement).value); setColor(hsvHex())" />
      <label class="appearance-hex"><span>HEX</span><input :value="selectedColor" :disabled="mode === 'card' && selected === 'cursorQuota'" maxlength="7" aria-label="十六进制颜色" @change="setColor(($event.target as HTMLInputElement).value)" /></label>
      <div class="appearance-swatches"><button v-for="color in ['#FFFFFF','#1B3331','#23B5A5','#3B8FD4','#D88A26','#E85A4F','#B78B00','#8B78BF']" :key="color" type="button" :style="{ background: color }" :aria-label="`选择 ${color}`" :disabled="mode === 'card' && selected === 'cursorQuota'" @click="setColor(color)" /></div>
      <template v-if="mode === 'water' && selected === 'base'"><label>底色透明度 <input type="range" min="0" max="100" :value="snapshot.settings.waterAppearance.inner.baseOpacity" @input="updateInner('baseOpacity', Number(($event.target as HTMLInputElement).value))" /></label></template>
      <template v-if="mode === 'water' && selected === 'liquid'"><label>液体颜色<select v-model="liquidColorChannel" class="codex-select"><option value="A">颜色 A</option><option value="B">颜色 B</option></select></label><label>液体配色<select class="codex-select" :value="snapshot.settings.waterAppearance.inner.palette" @change="updateInner('palette', ($event.target as HTMLSelectElement).value)"><option value="solid">纯色</option><option value="gradient">渐变</option><option value="aurora">炫彩</option></select></label><label>液体透明度 <input type="range" min="40" max="95" :value="snapshot.settings.waterAppearance.inner.opacity" @input="updateInner('opacity', Number(($event.target as HTMLInputElement).value))" /></label><label>水波幅度 <input type="range" min="4" max="12" :value="snapshot.settings.waterAppearance.inner.amplitude" @input="updateInner('amplitude', Number(($event.target as HTMLInputElement).value))" /></label><label>水波速度 <select class="codex-select" :value="snapshot.settings.waterAppearance.inner.motion" @change="updateInner('motion', ($event.target as HTMLSelectElement).value)"><option value="static">静止</option><option value="slow">缓慢</option><option value="normal">正常</option><option value="fast">快速</option></select></label></template>
      <template v-if="mode === 'water' && (selected === 'ring' || selected === 'track')"><label>环样式 <select class="codex-select" :value="snapshot.settings.waterAppearance.outer.style" @change="updateOuter('style', ($event.target as HTMLSelectElement).value)"><option value="solid">圆环</option><option value="segmented">固定分段</option></select></label><label>环宽 <input type="range" min="2" max="6" :value="snapshot.settings.waterAppearance.outer.thickness" @input="updateOuter('thickness', Number(($event.target as HTMLInputElement).value))" /></label><label>进度颜色<select class="codex-select" :value="snapshot.settings.waterAppearance.outer.colorMode" @change="updateOuter('colorMode', ($event.target as HTMLSelectElement).value)"><option value="quota">跟随额度状态</option><option value="custom">自定义</option></select></label><label>环光晕<select class="codex-select" :value="snapshot.settings.waterAppearance.outer.glow" @change="updateOuter('glow', ($event.target as HTMLSelectElement).value)"><option value="off">关闭</option><option value="soft">柔和</option><option value="strong">强</option></select></label></template>
      <div class="appearance-part-actions"><button type="button" :disabled="!selectableLayer(selected) || expanded.has(selected)" @click="detach">拆出</button><button type="button" :disabled="!expanded.has(selected)" @click="restore">放回</button></div>
      <template v-if="mode === 'water' && selected === 'reading'"><label><span>显示读数 <input type="checkbox" :checked="snapshot.settings.waterAppearance.inner.showPercent" @change="updateInner('showPercent', ($event.target as HTMLInputElement).checked)" /></span></label><label>文字位置<select class="codex-select" :value="snapshot.settings.waterAppearance.inner.percentPosition" @change="updateInner('percentPosition', ($event.target as HTMLSelectElement).value)"><option value="auto">自动</option><option value="center">居中</option><option value="bottom-left">左下</option><option value="bottom-right">右下</option></select></label><label>文字大小 <input type="range" min="12" max="32" :value="snapshot.settings.waterAppearance.inner.percentSize" @input="updateInner('percentSize', Number(($event.target as HTMLInputElement).value))" /></label></template>
    </div>
  </div>
</template>

<style scoped>
.appearance-studio{display:grid;grid-template-columns:minmax(260px,1fr) minmax(220px,280px);gap:12px;margin:12px 0;padding:10px;border:1px solid var(--codex-border,#dce7de);border-radius:14px;background:var(--codex-surface,#fff)}
.appearance-studio-stage-wrap{min-width:0}.appearance-studio-tabs{display:flex;align-items:center;gap:4px;padding:3px;border-radius:9px;background:color-mix(in srgb,var(--codex-surface-raised,#edf4ef) 80%,transparent)}.appearance-studio-tabs button{border:0;border-radius:7px;background:transparent;padding:7px 12px;color:var(--codex-muted,#61796e);font-size:12px;cursor:pointer}.appearance-studio-tabs button.active{background:var(--codex-surface,#fff);color:var(--codex-fg,#244238);box-shadow:0 1px 5px #1745351c}.appearance-studio-tabs .appearance-assembly{margin-left:auto;color:var(--codex-accent,#138574)}
.appearance-studio-stage{position:relative;display:grid;place-items:center;height:340px;margin-top:8px;overflow:hidden;border-radius:10px;perspective:800px;background:radial-gradient(ellipse at 50% 38%,#fafbf5,#e4efe5);touch-action:none}.appearance-studio-stage::before{content:'';position:absolute;inset:0;background-image:linear-gradient(#60907a0b 1px,transparent 1px),linear-gradient(90deg,#60907a0b 1px,transparent 1px);background-size:30px 30px;pointer-events:none}.appearance-studio-ball{position:relative;width:94px;height:94px;scale:2;transform-style:preserve-3d;transition:scale .4s}.appearance-studio-ball.exploded{scale:1.35}.appearance-layer,.appearance-complete{position:absolute;inset:0;transform-style:preserve-3d;transition:transform .65s cubic-bezier(.22,.7,.2,1);cursor:pointer}.appearance-layer:hover :deep(.codex-water-ball),.appearance-layer.selected :deep(.codex-water-ball){outline:2px solid #ffca46;outline-offset:2px}.appearance-complete.selected-base :deep(.codex-water-ball),.appearance-complete.hovered-base :deep(.codex-water-ball){outline:2px solid #ffca46;outline-offset:2px}.appearance-complete.selected-reading :deep(.codex-water-ball__value),.appearance-complete.hovered-reading :deep(.codex-water-ball__value){outline:2px solid #ffca46;outline-offset:1px;border-radius:5px}.appearance-complete.selected-ring :deep(.codex-water-ball__ring),.appearance-complete.hovered-ring :deep(.codex-water-ball__ring){filter:drop-shadow(0 0 2px #ffca46)}.appearance-complete.selected-liquid :deep(.codex-water-ball__liquid),.appearance-complete.hovered-liquid :deep(.codex-water-ball__liquid){outline:2px solid #ffca46;outline-offset:-2px}.appearance-layer-label{position:absolute;top:100%;left:50%;transform:translate(-50%,4px);padding:3px 5px;border:1px solid #d9e7db;border-radius:5px;background:#fffef8;color:#416554;font-size:7px;white-space:nowrap;cursor:pointer}
.layer-base :deep(.codex-water-ball__liquid),.layer-base :deep(.codex-water-ball__ring),.layer-base :deep(.codex-water-ball__value){visibility:hidden}.layer-liquid :deep(.codex-water-ball__surface::before){opacity:0}.layer-liquid :deep(.codex-water-ball__surface){box-shadow:none}.layer-liquid :deep(.refraction),.layer-liquid :deep(.glass-highlight),.layer-liquid :deep(.codex-water-ball__ring),.layer-liquid :deep(.codex-water-ball__value){visibility:hidden}.layer-track :deep(.codex-water-ball__surface),.layer-track :deep(.codex-water-ball__value),.layer-track :deep(.codex-water-ball__ring .value),.layer-track :deep(.codex-water-ball__ring .segment.active){visibility:hidden}.layer-ring :deep(.codex-water-ball__surface),.layer-ring :deep(.codex-water-ball__value),.layer-ring :deep(.codex-water-ball__ring .track),.layer-ring :deep(.codex-water-ball__ring .segment:not(.active)){visibility:hidden}.layer-reading :deep(.codex-water-ball__surface),.layer-reading :deep(.codex-water-ball__ring){visibility:hidden}
.appearance-layer{pointer-events:none}.appearance-layer-label,.layer-base :deep(.codex-water-ball__surface),.layer-liquid :deep(.codex-water-ball__liquid),.layer-reading :deep(.codex-water-ball__value){pointer-events:auto}.layer-track :deep(.codex-water-ball__ring circle),.layer-track :deep(.codex-water-ball__ring line),.layer-ring :deep(.codex-water-ball__ring circle),.layer-ring :deep(.codex-water-ball__ring line){pointer-events:visibleStroke}
.appearance-counter{transition:transform .6s;position:absolute;z-index:5;display:grid;min-width:20px;height:20px;place-items:center;border:2px solid #fff;border-radius:20px;color:#fff;font-weight:800;font-size:9px}.appearance-counter.input{left:0;bottom:0;background:#e5486f}.appearance-counter.active{right:0;bottom:23px;background:#258bc7}.appearance-counter.unread{right:0;bottom:0;background:#b84d91}
.appearance-card{position:relative;width:min(82%,340px);height:220px;transform-style:preserve-3d}.appearance-card button{position:absolute;text-align:left;font-size:11px;cursor:pointer}.appearance-card-surface{inset:0;border:1px solid var(--codex-border);border-radius:14px;background:var(--codex-surface)}.appearance-card-tabs,.appearance-card-search,.appearance-card-quota,.appearance-card-task{left:12px;right:12px;border:0;border-radius:6px;color:var(--codex-fg);background:var(--codex-surface-raised);padding:8px;transition:transform .5s}.appearance-card-tabs{top:12px}.appearance-card-search{top:52px;color:var(--codex-muted)}.appearance-card-quota{top:92px}.appearance-card-task{top:132px}.appearance-card button:hover,.appearance-card button.selected{outline:2px solid #ffca46;outline-offset:2px}

.appearance-studio-editor{display:grid;align-content:start;gap:9px;min-width:0;font-size:11px;color:var(--codex-muted,#607c6e)}.appearance-studio-editor label{display:grid;gap:5px}.appearance-color-heading{display:flex;justify-content:space-between;color:var(--codex-fg,#244238)}.appearance-spectrum{position:relative;height:112px;border-radius:8px;cursor:crosshair;touch-action:none;background-image:linear-gradient(to top,#000,transparent),linear-gradient(to right,#fff,transparent)}.appearance-spectrum i{position:absolute;width:12px;height:12px;border:2px solid white;border-radius:50%;box-shadow:0 0 0 1px #143b37;transform:translate(-50%,-50%);pointer-events:none}.appearance-hue{appearance:none;width:100%;height:8px;border-radius:8px;background:linear-gradient(to right,red,#ff0,#0f0,#0ff,#00f,#f0f,red)}.appearance-hue::-webkit-slider-thumb{appearance:none;width:15px;height:15px;border:2px solid #268778;border-radius:50%;background:white}.appearance-hex{display:flex!important;align-items:center;gap:8px;padding:6px;border:1px solid var(--codex-border,#dce7de);border-radius:7px}.appearance-hex input{min-width:0;flex:1;border:0;background:transparent;color:var(--codex-fg);font:inherit}.appearance-swatches,.appearance-part-actions{display:flex;gap:6px}.appearance-swatches button{width:20px;height:20px;border:1px solid #d9e5dc;border-radius:50%;cursor:pointer}.appearance-part-actions button{flex:1;padding:6px;border:1px solid var(--codex-border);border-radius:7px;background:transparent;color:var(--codex-fg);cursor:pointer}.appearance-studio-editor input[type=range]{width:100%;accent-color:var(--codex-accent,#138574)}
@media(max-width:700px){.appearance-studio{grid-template-columns:minmax(0,1fr) minmax(190px,240px)}.appearance-studio-stage{height:300px}}@media(max-width:520px){.appearance-studio{grid-template-columns:1fr}.appearance-studio-stage{height:300px}}
@media(prefers-reduced-motion:reduce){.appearance-layer,.appearance-studio-ball,.appearance-card button,.appearance-counter{transition:none!important}}
</style>
